// Generator today energy
// 62: Today_Gen_PowerWh (0.1kWh)

msg.baseAddr = 62;

msg.payload = {
    fc: 3,
    unitid: 1,
    address: 62,
    quantity: 1
};

return msg;

// Generator daily operating time
// 83: Generator daily operating time (0.1 hours)
// 240 = 24.0 hours

msg.baseAddr = 83;

msg.payload = {
    fc: 3,
    unitid: 1,
    address: 83,
    quantity: 1
};

return msg;

// Generator total energy
// 92: Total_Gen_powerWh Low word (0.1kWh)
// 95: Total_Gen_powerWh High word (0.1kWh)
// Note: registers are not contiguous (92 and 95)
// We read 92-95 (4 registers) and use [0] and [3]

msg.baseAddr = 92;

msg.payload = {
    fc: 3,
    unitid: 1,
    address: 92,
    quantity: 4    // 92, 93, 94, 95
};

return msg;

// Generator active power
// 166: Gen input power (1W, signed)
// Note: This register may also represent smart load power
// depending on inputMode setting

msg.baseAddr = 166;

msg.payload = {
    fc: 3,
    unitid: 1,
    address: 166,
    quantity: 1
};

return msg;

// Generator port voltage
// 181: Gen口的电压 (0.1V)

msg.baseAddr = 181;

msg.payload = {
    fc: 3,
    unitid: 1,
    address: 181,
    quantity: 1
};

return msg;

// Generator port frequency
// 196: 发电机口的频率 (0.01Hz)

msg.baseAddr = 196;

msg.payload = {
    fc: 3,
    unitid: 1,
    address: 196,
    quantity: 1
};

return msg;

// Build GeneratorDeviceState from multiple Modbus reads.
//
// Registers:
// 62     : Today_Gen_PowerWh (0.1kWh)
// 83     : Generator daily operating time (0.1 hours)
// 92     : Total_Gen_powerWh Low word (0.1kWh)
// 95     : Total_Gen_powerWh High word (0.1kWh)
// 166    : Gen input power (1W, signed)
// 181    : Gen port voltage (0.1V)
// 196    : Gen port frequency (0.01Hz)
//
// Note: Generator may not be connected - values may be 0 or null

let raw = msg.payload;

// node-red-contrib-modbus often sends { data: [...], buffer: ... }
let data = raw;
if (data && Array.isArray(data.data)) {
    data = data.data;
}

// Skip string errors like "Error: CRC error"
if (typeof raw === "string" || !Array.isArray(data)) {
    return null;
}

// Determine which block we just read
let baseAddr = msg.baseAddr;
if (typeof baseAddr !== "number") {
    baseAddr = (msg.modbusRequest && msg.modbusRequest.address);
}
if (typeof baseAddr !== "number") {
    node.warn("GeneratorDeviceState: missing base address on msg");
    return null;
}

// Helper: signed 16-bit
function s16(v) {
    if (!Number.isFinite(v)) return null;
    return (v & 0x8000) ? v - 0x10000 : v;
}

// Helper: combine two 16-bit words to 32-bit unsigned
function u32(low, high) {
    if (!Number.isFinite(low) || !Number.isFinite(high)) return null;
    return ((high & 0xFFFF) << 16) | (low & 0xFFFF);
}

// ---- Store partials in flow context ----

// Today Energy 62
if (baseAddr === 62) {
    const todayRaw = data[0] || 0;           // 0.1kWh
    const todayEnergy = todayRaw * 0.1;      // Convert to kWh

    flow.set("gen_part_today", {
        todayGenEnergyKWh: Math.round(todayEnergy * 100) / 100
    });
}

// Runtime 83
else if (baseAddr === 83) {
    const runtimeRaw = data[0] || 0;         // 0.1 hours
    const runtime = runtimeRaw * 0.1;        // Convert to hours

    flow.set("gen_part_runtime", {
        accumulatedRunTimeHours: Math.round(runtime * 10) / 10
    });
}

// Total Energy 92-95 (we read 4 registers, use [0] for 92 and [3] for 95)
else if (baseAddr === 92) {
    const totalLow = data[0] || 0;           // 92: low word
    const totalHigh = data[3] || 0;          // 95: high word
    const totalEnergy = u32(totalLow, totalHigh) * 0.1;  // Convert to kWh

    flow.set("gen_part_total", {
        totalGenEnergyKWh: Math.round(totalEnergy * 100) / 100
    });
}

// Power 166
else if (baseAddr === 166) {
    const powerRaw = s16(data[0]);           // 1W, signed

    flow.set("gen_part_power", {
        genActivePowerW: powerRaw,
        smartLoadActivePowerW: powerRaw      // Same register, different interpretation
    });
}

// Voltage 181
else if (baseAddr === 181) {
    const voltageRaw = data[0] || 0;         // 0.1V
    const voltage = voltageRaw * 0.1;        // Convert to V

    flow.set("gen_part_voltage", {
        genVoltageV: Math.round(voltage * 10) / 10
    });
}

// Frequency 196
else if (baseAddr === 196) {
    const freqRaw = data[0] || 0;            // 0.01Hz
    const freq = freqRaw * 0.01;             // Convert to Hz

    flow.set("gen_part_freq", {
        genFrequencyHz: Math.round(freq * 100) / 100
    });
}
else {
    return null;
}

// ---- Try to assemble full state ----

const todayPart = flow.get("gen_part_today");
const runtimePart = flow.get("gen_part_runtime");
const totalPart = flow.get("gen_part_total");
const powerPart = flow.get("gen_part_power");
const voltagePart = flow.get("gen_part_voltage");
const freqPart = flow.get("gen_part_freq");

// Require all parts
if (!todayPart || !runtimePart || !totalPart || !powerPart || !voltagePart || !freqPart) {
    return null;
}

// Resolve DeviceId
const deviceId = msg.deviceId
    || global.get("DEVICE_ID")
    || env.get("DEVICE_ID")
    || "EC100-DEV-001";

const state = {
    kind: "GeneratorDeviceState",
    timestampUtc: new Date().toISOString(),
    version: 1,
    DeviceId: deviceId,

    // Electrical
    genVoltageV: voltagePart.genVoltageV,
    genFrequencyHz: freqPart.genFrequencyHz,
    genActivePowerW: powerPart.genActivePowerW,

    // Smart-load mode (same as genActivePowerW, interpretation depends on mode)
    smartLoadActivePowerW: powerPart.smartLoadActivePowerW,

    // Energy / runtime stats
    todayGenEnergyKWh: todayPart.todayGenEnergyKWh,
    totalGenEnergyKWh: totalPart.totalGenEnergyKWh,
    accumulatedRunTimeHours: runtimePart.accumulatedRunTimeHours
};

// Clear partials for next cycle
flow.set("gen_part_today", null);
flow.set("gen_part_runtime", null);
flow.set("gen_part_total", null);
flow.set("gen_part_power", null);
flow.set("gen_part_voltage", null);
flow.set("gen_part_freq", null);

// Keep snapshot in flow
flow.set("generatorDeviceSnapshot", state);

// Put result on msg
msg.payload = state;
msg.state = state;

return msg;
